import heapq

def kClosest(points, k):
    # Squared distance to the origin; sqrt is unnecessary for ordering.
    def squared_distance(point):
        x, y = point
        return x * x + y * y

    # nsmallest keeps the k points with the smallest distance (the closest).
    return heapq.nsmallest(k, points, key=squared_distance)
